window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9b06e3075b7130af"]={"versions": [{"id": "FIG-9b06e3075b7130af", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram / Signalverlaufsdiagramm) zur Spezifikation des zeitbasierten Entprellmechanismus (Timer based debouncing) im Diagnostic Management (DM) der AUTOSAR Adaptive Platform. Das Diagramm stellt das Zusammenwirken von eingehenden Fehlermeldungen, dem internen Entprelltimer/-zähler und dem resultierenden UDS-Event-Status über einer gemeinsamen horizontalen Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei synchronisierte Signalspuren:</p>\n<ul class=\"fig-list\">\n<li><strong>Reports</strong>: Diskrete Eingabesignale/Meldungen mit den Werten <code>FAILED</code>, <code>PREFAILED</code>, neutraler Zustand, <code>PREPASSED</code> und <code>PASSED</code>.</li>\n<li><strong>Fault Detection Counter</strong>: Kontinuierlicher Entprellwert mit Null-Referenzlinie (<code>0</code>), oberem Schwellenwert <code>Failed</code> bzw. <code>FDC max (+127)</code> und unterem Schwellenwert <code>Passed</code> bzw. <code>FDC min (-128)</code>.</li>\n<li><strong>Event status</strong>: Qualifizierter Fehlerzustand mit den Zuständen <code>Failed</code> (schraffierter oberer Block), neutral/unqualifiziert und <code>Passed</code> (schraffierter unterer Block).</li>\n</ul>\n<p class=\"fig-p\">Parametrierte Zeitschwellen: <code>t failed</code> (Entprelldauer in Richtung Fehler) und <code>t passed</code> (Entprelldauer in Richtung Gutprüfung). Grüne Linien kennzeichnen direkte Zustandssprünge durch unqualifizierte/unentprellte Vollmeldungen (<code>PASSED</code>/<code>FAILED</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Bei Meldung von <code>PREFAILED</code> integriert der Entprellwert mit konstanter Steigung aufwärts; erreicht er innerhalb der Zeit <code>t failed</code> die Schwelle <code>FDC max (+127)</code>, wechselt <code>Event status</code> auf <code>Failed</code>.</li>\n<li>Bleibt <code>PREFAILED</code> über die Schwelle hinaus anstehen, verharrt der Entprellwert am oberen Anschlag (<code>FDC max</code>).</li>\n<li>Bei nachfolgendem <code>PREPASSED</code> sinkt der Wert mit konstanter Steigung ab; erreicht er innerhalb der Dauer <code>t passed</code> die Schwelle <code>FDC min (-128)</code>, schlägt <code>Event status</code> auf <code>Passed</code> um.</li>\n<li>Ein vorzeitiger Signalwechsel (z. B. <code>PREFAILED</code> vor Erreichen von <code>Passed</code>) bricht den vorherigen Entprellvorgang ab; der Zähler steigt von seinem aktuellen Zwischenwert erneut an (hier mit Sprung auf 0).</li>\n<li>Tritt eine direkte Vollmeldung <code>PASSED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf den Minimalwert <code>FDC min (-128)</code> und setzt den <code>Event status</code> auf <code>Passed</code>.</li>\n<li>Tritt eine direkte Vollmeldung <code>FAILED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf <code>FDC max (+127)</code> und setzt den <code>Event status</code> auf <code>Failed</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Entprellmechanismus definiert das normierte Verhalten des Diagnostic Event Manager bzw. Diagnostic Management bei zeitbasierter Entprellung:</p>\n<ul class=\"fig-list\">\n<li><code>PREFAILED</code>/<code>PREPASSED</code> erfordern das Durchlaufen der Integrationszeiten <code>t failed</code> bzw. <code>t passed</code> bis zum Setzen des qualifizierten Event-Status.</li>\n<li>Vollständige Statusmeldungen (<code>PASSED</code>/<code>FAILED</code>) überschreiben laufende Entprellungen sofort, setzen den Entprellwert direkt auf das jeweilige Extremum (<code>FDC min</code> bzw. <code>FDC max</code>) und aktualisieren den Event-Status ohne Verzögerung.</li>\n<li>Bei Richtungsumkehr ohne Erreichen der Schwellen erfolgt die Rückrechnung bzw. Rücksetzung gemäß den konfigurierten Übergangsregeln.</li>\n</ul>"}, {"id": "FIG-fd3210e2bc4c1746", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram / Signalverlaufsdiagramm) zur Spezifikation des zeitbasierten Entprellmechanismus (Timer based debouncing) im Diagnostic Management (DM) der AUTOSAR Adaptive Platform. Das Diagramm stellt das Zusammenwirken von eingehenden Fehlermeldungen, dem internen Entprelltimer/-zähler und dem resultierenden UDS-Event-Status über einer gemeinsamen horizontalen Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei synchronisierte Signalspuren:</p>\n<ul class=\"fig-list\">\n<li><strong>Reports</strong>: Diskrete Eingabesignale/Meldungen mit den Werten <code>FAILED</code>, <code>PREFAILED</code>, neutraler Zustand, <code>PREPASSED</code> und <code>PASSED</code>.</li>\n<li><strong>Debounce Time</strong>: Kontinuierlicher Entprellzeitwert über der horizontalen Zeitachse <code>t</code>, mit Null-Referenzlinie (<code>0</code>), oberem Schwellenwert <code>Failed</code> bzw. <code>FDC max (+127)</code> und unterem Schwellenwert <code>Passed</code> bzw. <code>FDC min (-128)</code>.</li>\n<li><strong>Event status</strong>: Qualifizierter Fehlerzustand mit den Zuständen <code>Failed</code> (schraffierter oberer Block), neutral/unqualifiziert und <code>Passed</code> (schraffierter unterer Block).</li>\n</ul>\n<p class=\"fig-p\">Parametrierte Zeitschwellen: <code>t failed</code> (Entprelldauer in Richtung Fehler) und <code>t passed</code> (Entprelldauer in Richtung Gutprüfung). Grüne Linien kennzeichnen direkte Zustandssprünge durch unqualifizierte/unentprellte Vollmeldungen (<code>PASSED</code>/<code>FAILED</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Bei Meldung von <code>PREFAILED</code> integriert der Entprellwert mit konstanter Steigung aufwärts; erreicht er innerhalb der Zeit <code>t failed</code> die Schwelle <code>FDC max (+127)</code>, wechselt <code>Event status</code> auf <code>Failed</code>.</li>\n<li>Bleibt <code>PREFAILED</code> über die Schwelle hinaus anstehen, verharrt der Entprellwert am oberen Anschlag (<code>FDC max</code>).</li>\n<li>Bei nachfolgendem <code>PREPASSED</code> sinkt der Wert mit konstanter Steigung ab; erreicht er innerhalb der Dauer <code>t passed</code> die Schwelle <code>FDC min (-128)</code>, schlägt <code>Event status</code> auf <code>Passed</code> um.</li>\n<li>Ein vorzeitiger Signalwechsel (z. B. <code>PREFAILED</code> vor Erreichen von <code>Passed</code>) bricht den vorherigen Entprellvorgang ab; der Zähler steigt von seinem aktuellen Zwischenwert erneut an (hier mit Sprung auf 0).</li>\n<li>Tritt eine direkte Vollmeldung <code>PASSED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf den Minimalwert <code>FDC min (-128)</code> und setzt den <code>Event status</code> auf <code>Passed</code>.</li>\n<li>Tritt eine direkte Vollmeldung <code>FAILED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf <code>FDC max (+127)</code> und setzt den <code>Event status</code> auf <code>Failed</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Entprellmechanismus definiert das normierte Verhalten des Diagnostic Event Manager bzw. Diagnostic Management bei zeitbasierter Entprellung:</p>\n<ul class=\"fig-list\">\n<li><code>PREFAILED</code>/<code>PREPASSED</code> erfordern das Durchlaufen der Integrationszeiten <code>t failed</code> bzw. <code>t passed</code> bis zum Setzen des qualifizierten Event-Status.</li>\n<li>Vollständige Statusmeldungen (<code>PASSED</code>/<code>FAILED</code>) überschreiben laufende Entprellungen sofort, setzen den Entprellwert direkt auf das jeweilige Extremum (<code>FDC min</code> bzw. <code>FDC max</code>) und aktualisieren den Event-Status ohne Verzögerung.</li>\n<li>Bei Richtungsumkehr ohne Erreichen der Schwellen erfolgt die Rückrechnung bzw. Rücksetzung gemäß den konfigurierten Übergangsregeln.</li>\n</ul>"}, {"id": "FIG-998b729a9a759a73", "releases": ["R18-03_R1.4.0", "R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram / Signalverlaufsdiagramm) zur Spezifikation des zeitbasierten Entprellmechanismus (Timer based debouncing) im Diagnostic Management (DM) der AUTOSAR Adaptive Platform. Das Diagramm stellt das Zusammenwirken von eingehenden Fehlermeldungen, dem internen Entprelltimer/-zähler und dem resultierenden UDS-Event-Status über einer gemeinsamen horizontalen Zeitachse dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei synchronisierte Signalspuren:</p>\n<ul class=\"fig-list\">\n<li><strong>Reports</strong>: Diskrete Eingabesignale/Meldungen mit den Werten <code>FAILED</code>, <code>PREFAILED</code>, neutraler Zustand, <code>PREPASSED</code> und <code>PASSED</code>.</li>\n<li><strong>Debounce Time</strong>: Kontinuierlicher Entprellzeitwert über der horizontalen Zeitachse <code>t</code>, mit Null-Referenzlinie (<code>0</code>), oberem Schwellenwert <code>Failed</code> bzw. <code>FDC max (+127)</code> und unterem Schwellenwert <code>Passed</code> bzw. <code>FDC min (-128)</code>.</li>\n<li><strong>Event status</strong>: Qualifizierter Fehlerzustand mit den Zuständen <code>Failed</code> (schraffierter oberer Block), neutral/unqualifiziert und <code>Passed</code> (schraffierter unterer Block).</li>\n</ul>\n<p class=\"fig-p\">Parametrierte Zeitschwellen: <code>t failed</code> (Entprelldauer in Richtung Fehler) und <code>t passed</code> (Entprelldauer in Richtung Gutprüfung). Grüne Linien kennzeichnen direkte Zustandssprünge durch unqualifizierte/unentprellte Vollmeldungen (<code>PASSED</code>/<code>FAILED</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Bei Meldung von <code>PREFAILED</code> integriert der Entprellwert mit konstanter Steigung aufwärts; erreicht er innerhalb der Zeit <code>t failed</code> die Schwelle <code>FDC max (+127)</code>, wechselt <code>Event status</code> auf <code>Failed</code>.</li>\n<li>Bleibt <code>PREFAILED</code> über die Schwelle hinaus anstehen, verharrt der Entprellwert am oberen Anschlag (<code>FDC max</code>).</li>\n<li>Bei nachfolgendem <code>PREPASSED</code> sinkt der Wert mit konstanter Steigung ab; erreicht er innerhalb der Dauer <code>t passed</code> die Schwelle <code>FDC min (-128)</code>, schlägt <code>Event status</code> auf <code>Passed</code> um.</li>\n<li>Ein vorzeitiger Signalwechsel (z. B. <code>PREFAILED</code> vor Erreichen von <code>Passed</code>) bricht den vorherigen Entprellvorgang ab; der Zähler steigt von seinem aktuellen Zwischenwert erneut an (hier mit Sprung auf 0).</li>\n<li>Tritt eine direkte Vollmeldung <code>PASSED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf den Minimalwert <code>FDC min (-128)</code> und setzt den <code>Event status</code> auf <code>Passed</code>.</li>\n<li>Tritt eine direkte Vollmeldung <code>FAILED</code> auf (grün hervorgehoben), springt der Zählerwert unmittelbar auf <code>FDC max (+127)</code> und setzt den <code>Event status</code> auf <code>Failed</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Entprellmechanismus definiert das normierte Verhalten des Diagnostic Event Manager bzw. Diagnostic Management bei zeitbasierter Entprellung:</p>\n<ul class=\"fig-list\">\n<li><code>PREFAILED</code>/<code>PREPASSED</code> erfordern das Durchlaufen der Integrationszeiten <code>t failed</code> bzw. <code>t passed</code> bis zum Setzen des qualifizierten Event-Status.</li>\n<li>Vollständige Statusmeldungen (<code>PASSED</code>/<code>FAILED</code>) überschreiben laufende Entprellungen sofort, setzen den Entprellwert direkt auf das jeweilige Extremum (<code>FDC min</code> bzw. <code>FDC max</code>) und aktualisieren den Event-Status ohne Verzögerung.</li>\n<li>Bei Richtungsumkehr ohne Erreichen der Schwellen erfolgt die Rückrechnung bzw. Rücksetzung gemäß den konfigurierten Übergangsregeln.</li>\n</ul>"}], "trans": [{"from": "FIG-9b06e3075b7130af", "to": "FIG-fd3210e2bc4c1746", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Achsen- bzw. Signalbeschriftung des mittleren Diagramms von „Fault Detection Counter“ in „Debounce Time“ geändert.</li>\n<li>Zeitachsenbeschriftung am rechten Pfeilende der horizontalen Achse um das Formelzeichen „t“ ergänzt.</li>\n<li>Umrahmung des gesamten Diagramms durch eine äußere Rahmenlinie hinzugefügt.</li>\n</ul>"}, {"from": "FIG-fd3210e2bc4c1746", "to": "FIG-998b729a9a759a73", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
